-- Северяночка: база данных PostgreSQL
-- Как запустить: открыть файл в DBeaver и выполнить скрипт (Alt+X)

DROP TABLE IF EXISTS reviews, products, categories, users CASCADE;

-- Категории каталога
CREATE TABLE categories (
    id    SERIAL PRIMARY KEY,
    slug  VARCHAR(50) NOT NULL,
    title VARCHAR(100) NOT NULL,
    image VARCHAR(255)
);

-- Товары
CREATE TABLE products (
    id          SERIAL PRIMARY KEY,
    article     INT NOT NULL,
    category_id INT REFERENCES categories(id),
    subcategory VARCHAR(100),
    title       VARCHAR(255) NOT NULL,
    description TEXT,
    price       NUMERIC(10,2) NOT NULL,
    card_price  NUMERIC(10,2),
    is_promo    BOOLEAN DEFAULT FALSE,
    is_new      BOOLEAN DEFAULT FALSE,
    in_stock    BOOLEAN DEFAULT TRUE,
    is_own      BOOLEAN DEFAULT FALSE,
    is_healthy  BOOLEAN DEFAULT FALSE,
    is_nogmo    BOOLEAN DEFAULT FALSE,
    brand       VARCHAR(100),
    country     VARCHAR(100),
    package     VARCHAR(50),
    bonus       INT DEFAULT 0,
    image       VARCHAR(255)
);

-- Отзывы
CREATE TABLE reviews (
    id         SERIAL PRIMARY KEY,
    product_id INT REFERENCES products(id),
    author     VARCHAR(100) NOT NULL,
    rating     INT NOT NULL,
    text       TEXT NOT NULL,
    created_at DATE DEFAULT CURRENT_DATE
);

-- Пользователи
CREATE TABLE users (
    id     SERIAL PRIMARY KEY,
    phone  VARCHAR(20) NOT NULL UNIQUE,
    name   VARCHAR(100) NOT NULL,
    avatar VARCHAR(255)
);





-- чтобы новые id продолжались после вставленных
SELECT setval('categories_id_seq', (SELECT MAX(id) FROM categories));
SELECT setval('products_id_seq', (SELECT MAX(id) FROM products));
